"""Write the human-readable OPEN_QUESTION_SPEC.md implementation report."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
def main():
 suite=json.loads((ROOT/"remaining_open_question_release_report.json").read_text(encoding="utf-8"));combined=json.loads((ROOT/"combined_open_question_report.json").read_text(encoding="utf-8"))
 lines=["# Open-question specification implementation report","","## Pre-change defect findings","","- `fold_punch`: 312 of 3,000 items had identical L4 and L5 question text and the identical `exactly half` answer. L5 was replaced only on those rows with the existing additional-fold counterfactual; all 3,000 L5 rows are now distinct from L4.","- `overlap_circles`: 1,034 of 3,000 L3 rows stored the field name `target_density`. Those answers are now `spread` for target overlap densities 0.28/0.34 and `clustered` for 0.40/0.46/0.52.","- `symmetry_pattern_0143`: no stored or rendered six-shape defect was present. The record has eight visible shapes in two complete 4-fold orbits. Across all 1,500 intact patterns, zero shape counts violate divisibility by rotational order. The permanent validator now asserts this invariant.","","## Per-domain validation and exclusions","","| Dataset | Version | Source | Included | Excluded | Exclusion reason(s) | Highest sub-fact baseline | Fields at or above 60% | Result |","|---|---|---:|---:|---:|---|---:|---|---|"]
 total_png=total_included=0
 versions=suite.get("version_bumps",{})
 for name,m in suite["datasets"].items():
  version=versions.get(name,{}).get("after") or m.get("dataset_version_after") or json.loads((ROOT/name/"build_manifest.json").read_text(encoding="utf-8"))["dataset_version"];highest=max(m["constant_answer_baselines"].values(),default=0);ex=", ".join(f"{k}: {v}" for k,v in m["exclusion_counts"].items()) or "none";high=", ".join(f"{k}: {v:.3f}" for k,v in m["fields_at_or_above_60_percent"].items()) or "none";lines.append(f"| `{name}` | `{version}` | {m['source_items']:,} | {m['included_items']:,} | {m['excluded_items']:,} | {ex} | {highest:.3f} | {high} | {m['status']} |" );total_png+=m["png_recovery"]["passed"];total_included+=m["included_items"]
 angle=suite["datasets"]["angle_estimation_dataset_3000"]["special_checks"];cube=suite["datasets"]["cube_structure_dataset_3000"]["special_checks"];hexa=suite["datasets"]["hex_pathfinding_dataset_3000"]["special_checks"];route=suite["datasets"]["route_dataset_3000"]["special_checks"];compass=suite["datasets"]["compass_bearing_dataset_3000"]["special_checks"];depth=suite["datasets"]["depth_height_dataset_3000"]["special_checks"];laser=suite["datasets"]["laser_mirror_dataset_3000"]["special_checks"]
 lines += ["","## Correctness findings","",f"- `cube_structure_0251`: `cubes_per_layer={json.dumps(cube['cube_structure_0251_cubes_per_layer'],sort_keys=True)}` and {cube['cube_structure_0251_z0_entries']} cube records have `z=0`. The ninth ground cube is fully concealed, so the old base-layer target was correct geometrically but unrecoverable visually. The replacement visible-top-face answer is {cube['cube_structure_0251_visible_top_faces']}.",f"- Cube-structure 20-image human comparison: {cube['human_vs_stored_20']['visible_top_face_divergences']} visible-top-face divergences and {cube['human_vs_stored_20']['hidden_cube_divergences']} hidden-cube divergences.",f"- `hex_pathfinding` uses {hexa['renderer_hex_orientation']} hexagons. Axial mapping: `{json.dumps(hexa['axial_offset_to_direction_name'],sort_keys=True)}`. Orientation-inadmissible stored directions: {hexa['orientation_inadmissible_stored_direction_count']}. Item 0124's `(1,0)` offset is horizontally aligned and therefore `right`.","","## Degenerate sub-fact dispositions","","| Domain | Previous sub-fact | Previous baseline | Disposition | New baseline |","|---|---|---:|---|---:|",f"| angle_estimation | largest_angle_vertex | 0.748 | Fixable label-order skew; sub-fact removed | — |",f"| coordinate_geometry | relation_to_10 | 0.649 | Fixable threshold skew; threshold changed to 12 | {suite['datasets']['coordinate_geometry_dataset_3000']['constant_answer_baselines'].get('relation_to_12',0):.3f} |",f"| fbd | weight_arrow | 0.833 | Inherent notation convention (`W`/`W1`); retained | {suite['datasets']['fbd_dataset_3000']['constant_answer_baselines'].get('weight_arrow',0):.3f} |",f"| gear_train | last_direction_relation | 0.618 | Fixable target-selection skew; deterministic balanced target | {suite['datasets']['gear_train_dataset_3000']['constant_answer_baselines'].get('target_direction_relation',0):.3f} |",f"| laser_mirror | reflection_count | 0.697 | Inherent after substantive zero-reflection exclusion; retained | {suite['datasets']['laser_mirror_dataset_3000']['constant_answer_baselines'].get('reflection_count',0):.3f} |",f"| overlap_circles | any_isolated | 0.720 | Fixable sampling skew; sub-fact removed | — |",f"| polyhedron | convexity | 0.895 | Inherent current solid-class mix; retained | {suite['datasets']['polyhedron_dataset_3000']['constant_answer_baselines'].get('convexity',0):.3f} |",f"| projectile_motion | peak_above_20_m | 0.654 | Fixable threshold skew; threshold changed to 13 m | {suite['datasets']['projectile_motion_dataset_1000']['constant_answer_baselines'].get('peak_above_13_m',0):.3f} |",f"| surface_topology | orientability | 0.750 | Inherent surface-family mix; retained | {suite['datasets']['surface_topology_dataset_3000']['constant_answer_baselines'].get('orientability',0):.3f} |","",f"Angle source label assignment: {angle['source_vertex_label_assignment']}; pre-fix distribution `{json.dumps(angle['pre_fix_largest_angle_vertex_distribution'],sort_keys=True)}`. Cross-variant populated fields: {0 if suite['datasets']['angle_estimation_dataset_3000']['assertions']['variant_specific_fields_only'] else 'FAIL'}.","","## Coverage audit","",f"- `angle_estimation` scene types: `{json.dumps(angle['scene_type_distribution'],sort_keys=True)}`; variant mapping violations: {angle['variant_mapping_violations']}.",f"- `route` endpoint counts: `{json.dumps(route['num_endpoints_distribution'],sort_keys=True)}`; chosen targets with degree below 1: {route['chosen_target_degree_below_1']}.",f"- `compass_bearing`: {compass['substantive_boundary_guard_exclusions']:,} exclusions, all from the 15-degree sector-boundary ambiguity guard; other reasons: {compass['other_exclusion_reasons']}.",f"- `depth_height`: {depth['stack_height_items_recovered_by_variant']:,} stack-height items recovered by the approved variant; template-failure exclusions: {depth['template_failure_exclusions']}.",f"- `laser_mirror`: {laser['zero_reflection_exclusions']:,} exclusions, all zero-reflection items; other reasons: {laser['other_exclusion_reasons']}.","","## Validation summary","",f"- Independent ground-truth mismatches: {sum(len(m['independent_derivation']['mismatches']) for m in suite['datasets'].values())}.",f"- Quantity-aware PNG recovery: {total_png:,}/{total_included:,} included images. Each per-domain metrics file lists the visible signal checked for every sub-fact and the supporting renderer/PNG validator evidence.","- Public schema: exactly `question_id,image,prompt` in every domain.","- Exact template wording, answer-leak checks, rendered-vocabulary checks, numeric tolerance checks, variant isolation, and one-to-one question/answer resolution: PASS in all 34 domains.",f"- Combined open files: {combined['combined_open_questions']:,} questions and {combined['combined_open_answers']:,} answers; {combined['resolved_image_paths']:,} referenced image paths resolve.","- Every complete answer distribution and baseline is retained in the per-domain `open_validation_metrics.json` files and the consolidated JSON report.","- Closed combined suite remains 500,000 questions, 500,000 answers, and 100,000 images."]
 (ROOT/"open_question_rewrite_report.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
 print("Wrote Dataset/open_question_rewrite_report.md")
if __name__=="__main__":main()
